P["YM-019"]=ly("用神妻财卯木:午月休、子日生;子孙亥水动生财且化申金回头生子孙,世应皆父母主长辈/婚书介入。本卦兑六冲变节六合。动化方向:亥水->申金回头生;反转条件:六冲主先散,变六合主后合,不径翻成。应期(k)月档婚事:逢值卯月/冲实酉月/填实卯月,取卯月窗数月内主坐标卯月;二路填实同点。粒度:可成断指针2条保留。",T())
P["YM-020"]=ly("用神妻财子水应静+初爻子水动两现,取动者:巳月死、未日克,动化官鬼寅木(用化鬼)泄克交加,兄弟辰土动克财化午火。动化方向:子水->寅木(化鬼泄用),辰土->午火;反转条件:用化鬼+月日克,凶链成立。应期(k)日档近病:逢值子日见危/冲实申日/填实子日,取子日窗旬内主坐标子日;二路填实同点。粒度:危重断指针>=2条保留。对象复述:妻财即寅命之妻。",T())
P["YM-022"]=ly("世兼身命主象官鬼午火动:子月休囚、申日耗,动化父母戌土入墓泄用;上爻父母戌土动化妻财寅木生世为救。动化方向:午火->戌土(化墓),戌土->寅木(化神生世);反转条件:化墓与化神生世并见未全立死断,只降格为困顿。应期(k)年档身命:化墓逢值戌年/冲墓辰年/逢值午年,取戌年窗数年内主坐标戌年;二路异点,墓闸门优先取戌、粒度降为年窗。粒度:等级降为灾病困顿带,不直断死。",T(di=True,rs="世官动化墓与上爻化财生世两象相冲突,故 disputed"))
P["YM-023"]=ly("用神官鬼:寅木应临月建旺相、卯木二爻动亦旺,午日生;动官化父母巳火(官化文书/印绶),初父巳火动化未土。动化方向:卯木->巳火(官泄化父),巳火->未土;反转条件:官旺临月,化泄不翻贵象。应期(k)年档贵显/大限:逢值寅年/填实卯年/冲实申年,取寅年窗数年内主坐标寅年;二路复推卯年异点,临月值年占优取寅、记降档理由于此。粒度:贵断指针2条保留,等级中上(官旺临月、无封疆级指针故不拔高)。",T())
P["YM-024"]=ly("天时晴以子孙酉金世为晴神:午月囚、卯日;父母巳火雨神两现,初爻父母巳火动应化官鬼寅木。动化方向:巳火->寅木(雨神化官泄火);反转条件:雨神动主先雨,晴神弱主迟晴。应期(k)日档天时:晴神逢值酉日/冲实申日/填实酉日,取酉日窗数日内主坐标酉日;二路填实同点。粒度:迟晴断指针2条保留。",T())
P["YM-025"]=ly("静卦天时:卦中无水爻(亥子皆缺)、无父母雨云之象成势,妻财酉金应与申金主金气收敛,子孙辰土世。动化方向:无动爻;反转条件:无。应期(k)日档明日事:以题面明日为窗,主坐标明日(甲寅日次日)无雨见晴;二路复推:无水象与金气两路同指不雨。粒度:不雨断指针2条(无水爻+无雨神动)保留。",T())
P["YM-027"]=ly("晴神子孙申金世动:午月克、申日临值,动化父母午火回头克晴神;父母午火动化兄弟辰土生子孙。动化方向:申金->午火(化回头克),午火->辰土(雨神化土生晴神);反转条件:两动互制未全立,取化土生晴神之路定迟晴。应期(k)日档天时兼秋成(年内附):逢值申日主即日反复/出晴主点取辰日(化神辰土逢值、生晴神),窗数日内主坐标辰日;二路异点按化神生用占优取辰。秋成面:子孙临日主收成尚可,已过闸保留为次断。",T(di=True,rs="子孙世动化回头克与父母动化土生子孙两路相冲突,故 disputed"))
P["YM-028"]=ly("静卦觅地以父母为用:父母戌土应、未土初两现,未土临日值;寅月克土,世妻财卯木克父母。动化方向:无动爻;反转条件:无。应期(k)月档觅地:逢值未月/冲实丑月/填实戌月,取未月窗数月内主坐标未月;二路复推日值未土同指未,同点。粒度:得地断指针1条(父临日值),降为倾向、等级带表述。",T(di=True,rs="父母临日值主有地讯,但世财克父母、月建克土主阻,两象并见故 disputed"))
P["YM-029"]=ly("父母(地/茔)不上卦:本宫艮首卦同位寻伏,伏神父母巳火于三爻兄弟辰土下(艮宫首卦三爻为父母巳火位),飞辰土泄伏,戌月生?土月火休囚,丑日;世官鬼寅木。动化方向:无动爻;反转条件:伏弱不径断不可用,地本身以世官与财应生世参断。应期(k)月档就地:逢值巳月/冲飞戌月/填实巳月,取丑月为就地主坐标系于日支土值与兄土地基逢值,窗数月内;二路异点,题面已有之地、就地取土值占优。粒度:可用断指针1条,降为倾向。",T(ru=True,rs="父母不上卦,启用伏神父母巳火参断,故 reserve_used"))
P["YM-030"]=ly("用神子孙亥水(胎):申月生、亥日临值,旺相;初爻官鬼巳火动克金不克水,反被亥水冲克,化妻财寅木泄鬼。本卦兑六冲变困六合。动化方向:巳火->寅木(鬼泄化财);反转条件:胎旺临日,鬼动不翻。应期(k)月档胎产:逢值亥月/冲实巳月已过取亥月/填实亥月,窗孕期内主坐标亥月安稳见分晓;二路填实同点。粒度:胎安断指针2条保留。对象复述:子孙即胎儿。",T())
P["YM-032"]=ly("静卦占男女,子孙不上卦:兑宫首卦四爻子孙亥水伏于父母丑土世下,飞丑土克伏,戌月辰日并克,伏弱;官鬼巳午两现阳爻居多与归妹卦象参断。动化方向:无动爻;反转条件:伏弱主育需保,不径断不育。性别断:伏子亥水为阴支、归妹主女象,取女。应期(k)月档胎产:以产期为窗,主坐标产时揭晓性别,不断具体产日(无据不报已记)。粒度:性别断指针1条(伏子阴支),降为倾向、低置信。",T(ru=True,di=True,rs="reserve_used:子孙伏藏启用伏神参断;disputed:官鬼两现阳象与伏子阴支/归妹女象相冲突,取伏子与卦象一侧"))
P["YM-033"]=ly("静卦求嗣,子孙亥水现于四爻:卯月休、申日生(原神兄弟酉金应与日申金气),世官巳火克金不碍子,子孙克官。动化方向:无动爻;反转条件:无。应期(k)年档求嗣:逢值亥年/冲实巳年/填实亥年,取亥年窗数年内主坐标亥年得子;二路填实同点。粒度:有子断指针2条(子现+得日生)保留。题面行善复卜之事实面已列:只作背景,不作盘面触发。",T())
P["YM-034"]=ly("占有花以子孙申金世为痘主/医药:丑月生相、卯日;官鬼卯木应动临日主痘毒发动,化兄弟丑土;兄弟丑土动化妻财亥水(化出子孙之源水)。动化方向:卯木->丑土(鬼化兄泄),丑土->亥水;反转条件:子旺相可制,发而不危。应期(k)日档痘发:鬼逢值卯日/子逢值申日/填实卯日,取卯日窗数日内主坐标卯日见痘发;二路填实同点。粒度:将发断指针2条保留,程度轻顺(子旺)。",T())
P["YM-035"]=ly("子孙申金世动:丑月生相、卯日,动化兄弟未土回头生子孙。官鬼卯木应临日静。动化方向:申金->未土回头生;反转条件:回头生主顺,不翻凶。应期(k)日档痘发:子逢值申日/填实申日/冲实寅日,取申日窗数日内主坐标申日见痘发而顺;二路填实同点。粒度:将发断指针2条保留。",T())
P["YM-037"]=ly("用神子孙寅木世:未月辰日耗泄休囚;父母申金动克子孙(忌),化兄弟亥水回头克父母为解一端;官鬼辰土动化兄弟亥水。动化方向:申金->亥水(忌化回头克自制),辰土->亥水;反转条件:忌神化制一端不足翻子弱受克主线。应期(k)日档近病痘疹:逢值寅日见危/冲实申日/填实寅日,取寅日窗旬内主坐标寅日病势转折偏危;二路填实同点。粒度:凶险断指针2条保留。对象复述:子孙即占者之子。",T())
P["YM-038"]=ly("静卦子病,子孙两现:应爻子孙戌土临月建旺、初(次)子孙丑土,取应戌土为主用;甲辰旬戌不空,辰日冲戌为冲动/冲值。官鬼亥水世。动化方向:无动爻,日冲旺用为暗动倾向;反转条件:无。应期(k)日档近病:逢值戌日/冲实戌日(日冲即是)/填实戌日,三路同指戌,窗旬内主坐标戌日转安;二路同点。粒度:可愈断指针2条保留。对象复述:子孙即己亥生之子。",T())
P["YM-039"]=ly("静卦妻病离六冲,用神妻财酉金:卯月冲酉月破,子日生金为救;子孙未丑土生财,官鬼亥水应。动化方向:无动爻;反转条件:月破待填实,日生一端不足翻破象主危。应期(k)日档近病:填实酉日/逢值酉日/冲实卯日不取,取酉日窗旬内主坐标酉日为危重转折点、终局仍偏不愈;二路逢值同点。粒度:危重断指针2条(月破+六冲)保留,日生救应记次。对象复述:妻财即程良玉之妻。",T(di=True,rs="妻财月破主危与子日生财、子孙生财之救并见,故 disputed"))
P["YM-040"]=ly("夫以官鬼亥水世为用:未月克、寅日泄,休囚;子孙戌土应动克官(克夫/医药两读),化官鬼子水回头克戌;兄弟午火动化妻财申金生官为救。动化方向:戌土->子水(化用回头克动爻),午火->申金(财生官链);反转条件:生克两链并见未全立,取克用主线终局偏凶。应期(k)日档近病:逢值亥日见危/冲实巳日/填实亥日,取亥日窗旬内主坐标亥日;二路填实同点。粒度:危重断指针2条保留。对象复述:官鬼即占者之夫。",T(di=True,rs="子孙动克官与兄弟化财生官两链相冲突,故 disputed"))
P["YM-042"]=ly("静卦妻身,妻财不上卦、变无、日支寅木非财亲(坎水宫财为火),月建午火即财亲,按用神不现以月为用:妻财午火临月建旺相;官鬼戌丑土泄财,子孙卯木初爻。初判无用神,复核月建为用后改主断,故 changed_main。动化方向:无动爻;反转条件:无。应期(k)日档近病:财逢值午日/填实午日/冲实子日(冲官?不取),取午日窗本月内主坐标午日转安;二路填实同点。粒度:可愈断指针1条(财临月建),降为倾向。对象复述:月建妻财即占者之妻。",T(cm=True,ru=True,rs="changed_main:初判财不上卦无从断,复核月建午火为财亲以月为用后改定可愈;reserve_used:用神不现,启用日月为用神(月建午火),故 reserve_used"))
P["YM-043"]=ly("用神父母午火动二爻:戌月相、申日耗,动化妻财亥水回头克父母;世官鬼寅木生父母为原神救,子孙申金应临日。动化方向:午火->亥水回头克;反转条件:世生用一端不足翻回头克主线。应期(k)日档近病:逢值午日见危/冲克亥之巳日/填实午日,取午日窗旬内主坐标午日病势转折偏危;二路填实同点。粒度:危重断指针2条保留。对象复述:父母即占者之父。",T(di=True,rs="父母动化回头克与世官生父母之救并见,故 disputed"))
